import * as React from "react";

export type PropertyControl =
  | {
      type: "text";
      value: string;
      placeholder?: string;
      onChange: (v: string) => void;
    }
  | {
      type: "number";
      value: number;
      min?: number;
      max?: number;
      step?: number;
      unit?: string;
      onChange: (v: number) => void;
    }
  | {
      type: "color";
      value: string;
      onChange: (v: string) => void;
    }
  | {
      type: "select";
      value: string;
      options: { value: string; label: string }[];
      onChange: (v: string) => void;
    }
  | {
      type: "toggle";
      value: boolean;
      onChange: (v: boolean) => void;
    }
  | {
      type: "slider";
      value: number;
      min: number;
      max: number;
      step?: number;
      onChange: (v: number) => void;
    }
  | {
      type: "custom";
      render: () => React.ReactNode;
    };

export interface PropertyRowDef {
  id: string;
  label: string;
  control: PropertyControl;
  hidden?: boolean;
}

export interface PropertySectionDef {
  id: string;
  title: string;
  rows: PropertyRowDef[];
  defaultOpen?: boolean;
  icon?: React.ElementType;
}

import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Slider } from "@/components/ui/slider";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { PropertyControl } from "./properties-panel-types";

interface PropertiesControlProps {
  control: PropertyControl;
}

export function PropertiesControl({ control }: PropertiesControlProps) {
  switch (control.type) {
    case "text":
      return (
        <Input
          value={control.value}
          placeholder={control.placeholder}
          onChange={(e) => control.onChange(e.target.value)}
          className="w-full h-7 text-[11px] px-2 bg-muted/50"
        />
      );

    case "number":
      return (
        <div className="flex items-center gap-1.5">
          <Input
            type="number"
            value={control.value}
            min={control.min}
            max={control.max}
            step={control.step ?? 1}
            onChange={(e) => control.onChange(Number(e.target.value))}
            className="h-7 text-[11px] font-mono px-2 bg-muted/50"
          />
          {control.unit && (
            <span className="text-[10px] text-muted-foreground/50 shrink-0 select-none">
              {control.unit}
            </span>
          )}
        </div>
      );

    case "color":
      return (
        <div className="flex items-center gap-2">
          <label className="relative cursor-pointer shrink-0">
            <div
              className="w-5 h-5 rounded border border-border"
              style={{ backgroundColor: control.value }}
            />
            <input
              type="color"
              value={control.value}
              onChange={(e) => control.onChange(e.target.value)}
              className="sr-only"
            />
          </label>
          <span className="text-[11px] font-mono text-muted-foreground">
            {control.value.toUpperCase()}
          </span>
        </div>
      );

    case "select":
      return (
        <Select value={control.value} onValueChange={control.onChange}>
          <SelectTrigger className="h-7 text-[11px] px-2 bg-muted/50">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {control.options.map((opt) => (
              <SelectItem
                key={opt.value}
                value={opt.value}
                className="text-[11px]"
              >
                {opt.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      );

    case "toggle":
      return (
        <Switch
          checked={control.value}
          onCheckedChange={control.onChange}
          className="scale-[0.8] origin-right"
        />
      );

    case "slider":
      return (
        <div className="flex items-center gap-2">
          <Slider
            value={[control.value]}
            min={control.min}
            max={control.max}
            step={control.step ?? 1}
            onValueChange={([v]) => control.onChange(v)}
            className="flex-1"
          />
          <span className="text-[10px] font-mono text-muted-foreground/50 w-6 text-right shrink-0 tabular-nums">
            {control.value}
          </span>
        </div>
      );

    case "custom":
      return <>{control.render()}</>;

    default:
      return null;
  }
}

PropertiesControl.displayName = "PropertiesControl";

import { cn } from "@/lib/utils";
import { PropertiesControl } from "./properties-panel-control";
import type { PropertyControl } from "./properties-panel-types";

export interface PropertiesRowProps {
  label: string;
  control: PropertyControl;
  className?: string;
  hidden?: boolean;
}

export function PropertiesRow({
  label,
  control,
  className,
  hidden,
}: PropertiesRowProps) {
  if (hidden) return null;

  const isToggle = control.type === "toggle";

  return (
    <div
      className={cn(
        "flex items-center gap-2 px-3 py-1.5 min-h-[32px]",
        isToggle && "justify-between",
        className,
      )}
    >
      <span
        className={cn(
          "text-[11px] text-muted-foreground/70 shrink-0 truncate select-none",

          isToggle ? "w-auto" : "basis-1/4 min-w-[24px] max-w-[80px]",
        )}
      >
        {label}
      </span>
      <div className={cn("flex-1 min-w-0", isToggle && "flex-none")}>
        <PropertiesControl control={control} />
      </div>
    </div>
  );
}

PropertiesRow.displayName = "PropertiesRow";

import * as React from "react";
import { IconChevronRight } from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import { PropertiesRow } from "./properties-panel-row";
import type { PropertyRowDef } from "./properties-panel-types";

export interface PropertiesSectionProps {
  title: string;
  rows?: PropertyRowDef[];
  defaultOpen?: boolean;
  icon?: React.ElementType;
  children?: React.ReactNode;
  className?: string;
}

export function PropertiesSection({
  title,
  rows,
  defaultOpen = true,
  icon: Icon,
  children,
  className,
}: PropertiesSectionProps) {
  const [open, setOpen] = React.useState(defaultOpen);

  return (
    <div className={cn("border-b border-border/60 last:border-0", className)}>
      <button
        type="button"
        onClick={() => setOpen((p) => !p)}
        className="flex items-center gap-2 w-full px-3 py-2 text-left hover:bg-muted/40 transition-colors group"
      >
        <IconChevronRight
          size={12}
          strokeWidth={2}
          className={cn(
            "text-muted-foreground/40 transition-transform shrink-0",
            open && "rotate-90",
          )}
        />
        {Icon && (
          <Icon
            size={12}
            strokeWidth={1.8}
            className="text-muted-foreground/50 shrink-0"
          />
        )}
        <span className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/70 select-none">
          {title}
        </span>
      </button>

      {open && (
        <div className="pb-1">
          {rows
            ?.filter((r) => !r.hidden)
            .map((row) => (
              <PropertiesRow
                key={row.id}
                label={row.label}
                control={row.control}
              />
            ))}

          {children}
        </div>
      )}
    </div>
  );
}

PropertiesSection.displayName = "PropertiesSection";

import * as React from "react";
import { cn } from "@/lib/utils";
import { PropertiesSection } from "./properties-panel-section";
import type { PropertySectionDef } from "./properties-panel-types";

export interface PropertiesPanelProps {
  /** Config-driven sections. Each section renders its rows automatically. */
  sections?: PropertySectionDef[];
  /** Headless children — use PropertiesSection + PropertiesRow directly. */
  children?: React.ReactNode;
  className?: string;
}

export function PropertiesPanel({
  sections,
  children,
  className,
}: PropertiesPanelProps) {
  return (
    <div
      className={cn(
        "flex flex-col rounded-md border border-border bg-card/80 overflow-hidden",
        className,
      )}
    >
      {sections?.map((section) => (
        <PropertiesSection
          key={section.id}
          title={section.title}
          rows={section.rows}
          defaultOpen={section.defaultOpen ?? true}
          icon={section.icon}
        />
      ))}

      {children}
    </div>
  );
}

PropertiesPanel.displayName = "PropertiesPanel";

export { PropertiesPanel } from "./properties-panel";
export { PropertiesSection } from "./properties-panel-section";
export { PropertiesRow } from "./properties-panel-row";
export { PropertiesControl } from "./properties-panel-control";
export type {
  PropertyControl,
  PropertyRowDef,
  PropertySectionDef,
} from "./properties-panel-types";
